const stations=[];function makeStation(name,x,z,scale){const s=new THREE.Group();s.position.set(x,0,z);s.userData={name};const base=new THREE.Mesh(new THREE.CylinderGeometry(scale,scale*1.13,.38,8),new THREE.MeshStandardMaterial({color:0x0c1736,metalness:.7,roughness:.25}));base.position.y=.18;s.add(base); for(let i=0;i<5;i++){const floor=new THREE.Mesh(new THREE.BoxGeometry(scale*1.45,.44,scale*1.1),new THREE.MeshStandardMaterial({color:0x101d43,emissive:0x071128,metalness:.5,roughness:.35}));floor.position.y=.65+i*.52;floor.userData={station:name,floor:i};s.add(floor)}const antenna=new THREE.Mesh(new THREE.ConeGeometry(.11,1.2,5),new THREE.MeshStandardMaterial({color:0x77dff5,emissive:0x1f8ca4}));antenna.position.y=3.45;s.add(antenna);group.add(s);stations.push(s)}
