function addTrace(record,index){const a=index*.7;const r=2.5+(index%4)*.3;const p=new THREE.Vector3(Math.cos(a)*r,1.1+(index%5)*.45,Math.sin(a)*r);const dot=new THREE.Mesh(new THREE.SphereGeometry(.12,12,12),new THREE.MeshStandardMaterial({color:colors[record.type],emissive:colors[record.type],emissiveIntensity:2}));dot.position.copy(p);dot.userData={record};trace.add(dot);const target=stations[0].position.clone();target.y=1.2+(index%5)*.5;const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([p,target]),new THREE.LineBasicMaterial({color:colors[record.type],transparent:true,opacity:.42}));trace.add(line)}
function setReveal(n){revealed=n;while(trace.children.length)trace.remove(trace.children[0]);for(let i=0;i<n;i++)addTrace(records[i],i);const r=records[Math.max(0,n-1)];document.querySelector('#eventNumber').textContent=n;document.querySelector('#scrubber').value=Math.max(0,n-1);document.querySelector('#sequence').textContent=n?`SEQ ${r.seq}`:'SEQ —';document.querySelector('#timestamp').textContent=n?`2026-09-01 · ${r.time} UTC`:'READY';if(n)inspect(r)}
